1	// Re-export everything from the shared adapter-utils/server-utils package.
2	// This file is kept as a convenience shim so existing in-tree
3	// imports (process/, http/, heartbeat.ts) don't need rewriting.
4	import type { ChildProcess } from "node:child_process";
5	import { logger } from "../middleware/logger.js";
6	import * as serverUtils from "@paperclipai/adapter-utils/server-utils";
7	export type { RunProcessResult } from "@paperclipai/adapter-utils/server-utils";
8	import type { CommandExecutor } from "@paperclipai/adapter-utils/executor";
9	
10	type BuildInvocationEnvForLogsOptions = {
11	  runtimeEnv?: NodeJS.ProcessEnv | Record<string, string>;
12	  includeRuntimeKeys?: string[];
13	  resolvedCommand?: string | null;
14	  resolvedCommandEnvKey?: string;
15	};
16	
17	export const runningProcesses: Map<string, { child: ChildProcess; graceSec: number; processGroupId: number | null }> =
18	  serverUtils.runningProcesses;
19	export const MAX_CAPTURE_BYTES = serverUtils.MAX_CAPTURE_BYTES;
20	export const MAX_EXCERPT_BYTES = serverUtils.MAX_EXCERPT_BYTES;
21	export const parseObject = serverUtils.parseObject;
22	export const asString = serverUtils.asString;
23	export const asNumber = serverUtils.asNumber;
24	export const asBoolean = serverUtils.asBoolean;
25	export const asStringArray = serverUtils.asStringArray;
26	export const parseJson = serverUtils.parseJson;
27	export const appendWithCap = serverUtils.appendWithCap;
28	export const appendWithByteCap = serverUtils.appendWithByteCap;
29	export const resolvePathValue = serverUtils.resolvePathValue;
30	export const renderTemplate = serverUtils.renderTemplate;
31	export const redactEnvForLogs = serverUtils.redactEnvForLogs;
32	export const buildPaperclipEnv = serverUtils.buildPaperclipEnv;
33	export const defaultPathForPlatform = serverUtils.defaultPathForPlatform;
34	export const ensurePathInEnv = serverUtils.ensurePathInEnv;
35	export const ensureAbsoluteDirectory = serverUtils.ensureAbsoluteDirectory;
36	export const ensureCommandResolvable = serverUtils.ensureCommandResolvable;
37	export const resolveCommandForLogs = serverUtils.resolveCommandForLogs;
38	
39	export function buildInvocationEnvForLogs(
40	  env: Record<string, string>,
41	  options: BuildInvocationEnvForLogsOptions = {},
42	): Record<string, string> {
43	  const maybeBuildInvocationEnvForLogs = (
44	    serverUtils as typeof serverUtils & {
45	      buildInvocationEnvForLogs?: (
46	        env: Record<string, string>,
47	        options?: BuildInvocationEnvForLogsOptions,
48	      ) => Record<string, string>;
49	    }
50	  ).buildInvocationEnvForLogs;
51	
52	  if (typeof maybeBuildInvocationEnvForLogs === "function") {
53	    return maybeBuildInvocationEnvForLogs(env, options);
54	  }
55	
56	  const merged: Record<string, string> = { ...env };
57	  const runtimeEnv = options.runtimeEnv ?? {};
58	
59	  for (const key of options.includeRuntimeKeys ?? []) {
60	    if (key in merged) continue;
61	    const value = runtimeEnv[key];
62	    if (typeof value !== "string" || value.length === 0) continue;
63	    merged[key] = value;
64	  }
65	
66	  const resolvedCommand = options.resolvedCommand?.trim();
67	  if (resolvedCommand) {
68	    merged[options.resolvedCommandEnvKey ?? "PAPERCLIP_RESOLVED_COMMAND"] = resolvedCommand;
69	  }
70	
71	  return redactEnvForLogs(merged);
72	}
73	
74	// Re-export runChildProcess with the server's pino logger wired in.
75	const _runChildProcess = serverUtils.runChildProcess;
76	
77	export async function runChildProcess(
78	  runId: string,
79	  command: string,
80	  args: string[],
81	  opts: {
82	    cwd: string;
83	    env: Record<string, string>;
84	    timeoutSec: number;
85	    graceSec: number;
86	    onLog: (stream: "stdout" | "stderr", chunk: string) => Promise<void>;
87	    executor?: CommandExecutor;
88	  },
89	): Promise<RunProcessResult> {
90	  if (opts.executor) {
91	    return opts.executor.run({
92	      runId,
93	      command,
94	      args,
95	      cwd: opts.cwd,
96	      env: opts.env,
97	      timeoutSec: opts.timeoutSec,
98	      graceSec: opts.graceSec,
99	      onLog: opts.onLog,
100	    });
101	  }
102	  return _runChildProcess(runId, command, args, {
103	    ...opts,
104	    onLogError: (err, id, msg) => logger.warn({ err, runId: id }, msg),
105	  });
106	}
